"""Update the existing feature pair to the owner's approved open kick log."""
from pathlib import Path
import argparse
import json
import re

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'artifacts/round-penalties-log-2026-11-06'
parser = argparse.ArgumentParser()
parser.add_argument('--finish', action='store_true')
args = parser.parse_args()

def replace_section(relative, heading, content):
    path = ROOT / relative
    body = path.read_text(encoding='utf-8-sig')
    pattern = r'^## ' + re.escape(heading) + r'\n.*?(?=^## |\Z)'
    updated, count = re.subn(pattern, lambda _: '## ' + heading + '\n\n' + content.strip() + '\n\n', body, flags=re.M | re.S)
    assert count == 1, (relative, heading, count)
    path.write_text(updated, encoding='utf-8')

def prepend(relative, heading, content):
    path = ROOT / relative
    body = path.read_text(encoding='utf-8-sig')
    marker = '## ' + heading
    if marker not in body:
        first, rest = body.split('\n', 1)
        path.write_text(first + '\n\n' + marker + '\n\n' + content.strip() + '\n' + rest, encoding='utf-8')

